import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def main():
  helpers.print_header("Upgrading macOS updates ...")
  rc = subprocess.run(["sudo", "softwareupdate", "--install", "--all", "--restart"], check=False).returncode
